function setValue(record, fullPath, value) {

  if(Array.isArray(record)){
    return record.map(x => setValue(x, fullPath, value))
  }


  let pathItems = fullPath.split('.')

  // Get path item
  let path = pathItems[0]
  path = path.split('[')[0]
  let pathItemsRemaining = pathItems.slice(1)


  // Get path position
  let pathPosition = pathItems[0].split('[')?.[1]
  if (pathPosition) {
    pathPosition = pathPosition.split(']')?.[0] || 0
    try {
      pathPosition = parseInt(pathPosition || 0)
    } catch (error) {

    }
  } else {
    pathPosition = 0
  }


  // Create values if missing items
  let subRecords = record?.[path] || []
  subRecords = Array.isArray(subRecords) ? subRecords : [subRecords]

  // Add values is position less than length
  while (subRecords.length < pathPosition + 1) {
    subRecords.push({  })
  }
  record[path] = subRecords

  // Set value
  if (pathItemsRemaining && pathItemsRemaining.length > 0) {

    let currentValue = record[path][pathPosition]
    record[path][pathPosition] = setValue(currentValue, pathItemsRemaining.join('.'), value)

  } else {
    record[path][pathPosition] = value
  }


  // Clean up
  if(record[path].length === 0){
    record[path] = undefined
  }

  if(record[path].length === 1){
    record[path] = record[path][0]
  }

  return record
}



